//! O-152: oxa's built-in skills and the identity file (architect-owned).
//!
//! * **Built-in skills** are embedded in the binary ([`BUILTIN_SKILLS`]). Discovery lists them
//!   at fixed paths under [`builtin_skills_dir`] (so the prefix bytes never depend on whether
//!   they were written yet); [`install_builtin_skills`] writes the files there so the model can
//!   read their bodies on demand (pi's skill model). Any other skill of the same name wins.
//! * **The identity** (`<agent dir>/identity.md`) is generated by `oxa identity --refresh` at
//!   install and update and read once per epoch by `discover` ([`read_identity`]). A missing or
//!   empty file is `None`; the prefix then carries a generic fallback (never an error).
use crate::skills::SKILL_FILE;
use oxa_config::Dirs;
use oxa_proto::OxaError;
use std::path::{Path, PathBuf};

/// `(name, SKILL.md content)` of every built-in skill, sorted by name.
pub const BUILTIN_SKILLS: &[(&str, &str)] = &[
    ("ox-llm", include_str!("../builtin-skills/ox-llm/SKILL.md")),
    (
        "oxa-extend",
        include_str!("../builtin-skills/oxa-extend/SKILL.md"),
    ),
    (
        "pull-request",
        include_str!("../builtin-skills/pull-request/SKILL.md"),
    ),
    (
        "report-issue",
        include_str!("../builtin-skills/report-issue/SKILL.md"),
    ),
];

/// The identity file inside the agent directory.
pub const IDENTITY_FILE: &str = "identity.md";

/// The setting that turns the built-in skills off (`oxa.builtinSkills: false`).
pub const SETTING_BUILTIN_SKILLS: &str = "oxa.builtinSkills";

/// Where the built-in skills are written: `<agent dir>/builtin-skills`.
pub fn builtin_skills_dir(dirs: &Dirs) -> PathBuf {
    dirs.agent_dir.join("builtin-skills")
}

/// The `SKILL.md` path of the built-in skill `name`.
pub fn builtin_skill_path(dirs: &Dirs, name: &str) -> PathBuf {
    builtin_skills_dir(dirs).join(name).join(SKILL_FILE)
}

/// Write every built-in skill whose file is missing or differs (atomic rename; files that are
/// already current are not touched). Returns the paths written. Called by `oxa identity
/// --refresh` and when the binary starts a session.
pub fn install_builtin_skills(dirs: &Dirs) -> Result<Vec<PathBuf>, OxaError> {
    let mut written = Vec::new();
    for (name, content) in BUILTIN_SKILLS {
        let path = builtin_skill_path(dirs, name);
        if std::fs::read(&path).is_ok_and(|b| b == content.as_bytes()) {
            continue;
        }
        write_atomic(&path, content.as_bytes())
            .map_err(|e| OxaError::io(&format!("cannot write the built-in skill {}", path.display()), &e))?;
        written.push(path);
    }
    Ok(written)
}

/// `<agent dir>/identity.md`.
pub fn identity_path(dirs: &Dirs) -> PathBuf {
    dirs.agent_dir.join(IDENTITY_FILE)
}

/// The identity text exactly as on disk (a trailing newline removed), `None` when the file is
/// missing, unreadable or blank.
pub fn read_identity(dirs: &Dirs) -> Option<String> {
    let text = std::fs::read_to_string(identity_path(dirs)).ok()?;
    let text = text.strip_suffix('\n').unwrap_or(&text);
    (!text.trim().is_empty()).then(|| text.to_string())
}

/// Write `bytes` to `path` through a temporary sibling and a rename (parents created).
pub fn write_atomic(path: &Path, bytes: &[u8]) -> std::io::Result<()> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    let tmp = path.with_extension(format!("tmp.{}", std::process::id()));
    std::fs::write(&tmp, bytes)?;
    std::fs::rename(&tmp, path)
}
